  const judged = () => writeServerEvent({ name: 'ads_v2_product_locked', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, idx: row.idx, attempt: row.attempt, mode: 'in_hand', frame: tag?.frame ?? null, ...(tag?.object ? { object: tag.object } : {}), try: ih ? ih.adsV2InHandTry(row.reason) : null, verdict: verdict ? { ok: verdict.ok, fails: verdict.fails, ...(verdict.unsure?.length ? { unsure: verdict.unsure } : {}), ...(typeof verdict.crop === 'boolean' ? { crop: verdict.crop } : {}) } : null, step, ...(step === 'best' ? { best: softOnly ? 'soft_only' : 'packshot_cap' } : {}), ...(packshotsUsed !== null ? { packshots_used: packshotsUsed } : {}), charged: false } }).catch(() => null) // KINEO-ADS-PRODUTO-NA-MAO-1610 · KINEO-ADS-MAO-AJUSTE-3-1610 — + object no evento · KINEO-ADS-MAO-JUIZ-1610 — + best (por quê) e packshots_used
  if (step === 'keep') { if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: stored })) await judged(); return } // KINEO-ADS-PRODUTO-NA-MAO-1610
