  } // KINEO-ADS-PRODUTO-NA-MAO-1610
  if (tag && (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: tag.fallbackUrl, reason: null }))) { await judged(); await shotFallbackEvent(order, row, { to: 'product_photo', reason: 'in_hand_label' }) } // KINEO-ADS-PRODUTO-NA-MAO-1610 — a foto real do produto (o fallback de sempre)
